mapper.select:
select A.*, B.TRADE_ID tradeIdAdd, B.REPO_TYPE, B.CON_PRICE, B.CON_AMT, B.CON_PRIN_AMT, B.R_FINPROD_ID, B.SE_REP_DAY_TYPE, C.CHECK_RESULT, F.TRADE_ID PLEDGE_TRADE_ID, F.BRANCH pledgeBranch, F.PLEDGE_FINPROD_ID, F.PLEDGE_FACE_VALUE, F.PLEDGE_NUMBER, F.PLEDGE_RATIO,F.PLEDGE_AMT,F.DISPLACE_DIRECTION from SETTLE_TRANS_DATA A left join SETTLE_TRANS_DATA_ADD B on A.TRADE_ID = B.TRADE_ID left join SETTLE_TRANS_DATA_STATUS C on A.TRADE_ID = C.TRADE_ID left join SETTLE_TRANS_DATA_TOTAL D on A.DEAL_DATE = D.DEAL_DATE and A.APPLY_TRADE_ID = D.APPLY_TRADE_ID and A.SEAT_NUMBER = D.SEAT_NUMBER left join SETTLE_TRANS_DATA_TOTAL_STATUS E on D.SEQ_ID= E.SEQ_NO left join SETTLE_TRANS_DATA_PLEDGE F on A.TRADE_ID= F.TRADE_ID where A.DEAL_DATE = #{dealDate,jdbcType=DATE}
and (E.MATCH_STATUS is null or E.MATCH_STATUS = #{matchStatus})
and (A.APPLY_TRADE_ID is not null OR ((B.REPO_TYPE = #{REPO_TYPE_H02} AND A.PS!= #{PS_T07}) OR A.PS = #{PS_T46} OR A.PS = #{PS_T97}))
and A.PS !=#{PS_T05}
and A.DELIVERY_RESULT IN (#{DELIVERY_RESULT_01}, #{DELIVERY_RESULT_02})
